import{c as a,Q as t,j as r,m as n}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Technical Report: Evaluating Goal Drift in Language Model Agents","description":"","frontmatter":{"url":"https://arxiv.org/abs/2505.02709","title":"Technical Report: Evaluating Goal Drift in Language Model Agents","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2505.02709,"authors":["Rauno Arike","Elizabeth Donoway","Henning Bartsch","Marius Hobbhahn"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2505.02709v1","pdf_path":"pdfs/2505.02709.pdf","published_date":"2025-05-05T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-05-05-evaluating-goal-drift-language-model-agents-2505-02709.md","filePath":"research/papers/2025-05-05-evaluating-goal-drift-language-model-agents-2505-02709.md","lastUpdated":1785909234000}'),o={name:"research/papers/2025-05-05-evaluating-goal-drift-language-model-agents-2505-02709.md"};function i(s,e,l,g,d,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="technical-report-evaluating-goal-drift-in-language-model-agents" tabindex="-1">Technical Report: Evaluating Goal Drift in Language Model Agents <a class="header-anchor" href="#technical-report-evaluating-goal-drift-in-language-model-agents" aria-label="Permalink to &quot;Technical Report: Evaluating Goal Drift in Language Model Agents&quot;">​</a></h1><p><strong>Authors</strong>: Rauno Arike, Elizabeth Donoway, Henning Bartsch, Marius Hobbhahn <strong>Published</strong>: May 5, 2025 <strong>Source</strong>: <a href="https://arxiv.org/abs/2505.02709" target="_blank" rel="noreferrer">https://arxiv.org/abs/2505.02709</a> · <a href="https://arxiv.org/html/2505.02709v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2505.02709 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2505.02709" target="_blank" rel="noreferrer">research/papers/pdfs/2505.02709.pdf</a> (36 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>As language models (LMs) are increasingly deployed as autonomous agents, their robust adherence to human-assigned objectives becomes crucial for safe operation. When these agents operate independently for extended periods without human oversight, even initially well-specified goals may gradually shift. Detecting and measuring goal drift - an agent&#39;s tendency to deviate from its original objective over time - presents significant challenges, as goals can shift gradually, causing only subtle behavioral changes. This paper proposes a novel approach to analyzing goal drift in LM agents. In our experiments, agents are first explicitly given a goal through their system prompt, then exposed to competing objectives through environmental pressures. We demonstrate that while the best-performing agent (a scaffolded version of Claude 3.5 Sonnet) maintains nearly perfect goal adherence for more than 100,000 tokens in our most difficult evaluation setting, all evaluated models exhibit some degree of goal drift. We also find that goal drift correlates with models&#39; increasing susceptibility to pattern-matching behaviors as the context length grows.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出量測 LM agent <strong>goal drift</strong>（隨時間偏離原始目標的傾向）的新方法論：先以 system prompt 明確賦予目標，再透過 <strong>environmental pressures</strong>（環境壓力）注入競爭目標，觀測長程行為偏移。</li><li>將 goal drift 定義為一個可量化的安全評估維度，針對 agent 在<strong>無人監督長時間自主運行</strong>情境設計，捕捉 subtle、漸進式的行為變化（而非單次明顯違規）。</li><li>跨多個 model 進行對照評估，量化各 model 在不同難度設定下的目標維持能力。</li><li>揭示 goal drift 與 <strong>context length 增長下的 pattern-matching 易感性</strong>之間的相關性，提供退化的機制性線索。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>表現最佳的 agent（scaffolded 版本的 <strong>Claude 3.5 Sonnet</strong>）在最困難評估設定下，於 <strong>&gt;100,000 tokens</strong> 內維持近乎完美的 goal adherence。</li><li><strong>所有受測 model 皆呈現某種程度的 goal drift</strong>——無 model 完全免疫。</li><li>goal drift 與 model 隨 context 變長而<strong>增加的 pattern-matching 行為傾向正相關</strong>（context 越長越易被環境模式帶偏）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><p>文件摘要未列明確 limitation 章節；以下為基於摘要的判斷弱點：</p><ul><li>評估以<strong>合成的 environmental pressure</strong>情境驅動，與真實部署中多樣化、未預期的競爭目標分布是否一致存疑（external validity）。</li><li>「near-perfect adherence」高度依賴特定 scaffolding；scaffold 設計差異可能主導結果，難以歸因到 base model 本身的 robustness。</li><li>pattern-matching 相關性為<strong>相關非因果</strong>；未必證明 pattern-matching 是 drift 的成因。</li><li>100k tokens 上限對更長程（百萬 token 級）自主運行的外推未驗證。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>直接對應 The Loop **IDENTIFY 階段的「可機械驗證成功條件」**紀律：本論文證明 LM agent 在長 context 下會漸進偏離初始目標，正是「弱成功條件（make it work）會被 drift 侵蝕、需強條件持續錨定目標」的實證背書。⚠️ 落地門檻：論文量測對象是單一 agent 長程 session，workspace 的多階段委派場景需額外設計目標重申機制才能套用其量測法。</li><li>呼應 <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>）的 <strong>dynamic workflow 三失敗模式（goal drift / agentic laziness / self-preferential bias）</strong>：本文為 goal drift 提供可量化的偵測框架，可作為「subagent verdict 非證據、須機械重驗」原則的上游理論依據。⚠️ 落地門檻：論文方法需特製 evaluation harness，無法直接嫁接到現有 healthcheck/grep 重驗流程。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li>對長程 agentic 任務的 <strong>context-management</strong> 有警示意義：drift 與 context length 增長下的 pattern-matching 易感性相關，支持 workspace 「長 agentic 30–35% 主動 compact」的偏好——縮短有效 context 或可降低 drift 風險。⚠️ 落地門檻：compact 本身可能丟失原始目標錨點（context-management.md 已警示 compact 後須自檢「任務目標仍在？」），需平衡。</li><li>pattern-matching 易感性發現可作為 <strong>RECORD 階段自我演化迴圈</strong>設計輸入：若長 session 中行為退化可被 drift 指標捕捉，則可觸發結構化反思而非靜默續跑。⚠️ 落地門檻：workspace 目前無自動 drift 量測，屬研究候選非既成能力。</li></ul>',17)])])}const u=a(o,[["render",i]]);export{p as __pageData,u as default};
